    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    rf"(?:-({_IDENTIFIER}(?:\.{_IDENTIFIER})*))?"
    rf"(?:\+({_IDENTIFIER}(?:\.{_IDENTIFIER})*))?$"
)
_COMPARATOR_RE = re.compile(r"^(>=|<=|>|<|=|\^|~)?(.*)$")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")

    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    pre_text, build_text = match.group(4), match.group(5)
    prerelease = tuple(pre_text.split(".")) if pre_text else ()
    build = tuple(build_text.split(".")) if build_text else ()

    # Numeric pre-release identifiers must not have leading zeros.
    for identifier in prerelease:
        if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(f"invalid version: {text!r}")

    return Version(
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        prerelease,
        build,
    )


def _coerce(value: str | Version) -> Version:
    return parse(value) if isinstance(value, str) else value


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()
    if a_numeric and b_numeric:
        a_value, b_value = int(a), int(b)
        return (a_value > b_value) - (a_value < b_value)
    if a_numeric != b_numeric:
        return -1 if a_numeric else 1
    return (a > b) - (a < b)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _coerce(a), _coerce(b)

    if a.major != b.major:
        return (a.major > b.major) - (a.major < b.major)
    if a.minor != b.minor:
        return (a.minor > b.minor) - (a.minor < b.minor)
    if a.patch != b.patch:
        return (a.patch > b.patch) - (a.patch < b.patch)

    if not a.prerelease and not b.prerelease:
        return 0
