    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}
_DOW_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}


def _field_value(text: str, low: int, high: int, names: dict[str, int] | None) -> int:
    if names is not None:
        named = names.get(text.upper())
        if named is not None:
            return named
    if not text.isdigit():
        raise ValueError(f"invalid cron value: {text!r}")
    value = int(text)
    if not low <= value <= high:
        raise ValueError(f"cron value out of range: {text!r}")
    return value


def _parse_field(
    text: str, low: int, high: int, names: dict[str, int] | None = None
) -> set[int]:
    values: set[int] = set()
    items = text.split(",")
    if not items:
        raise ValueError("empty cron field")

    for item in items:
        if not item:
            raise ValueError("empty cron item")

        base, slash, step_text = item.partition("/")
        if slash:
            if not step_text.isdigit() or int(step_text) <= 0:
                raise ValueError(f"invalid cron step: {item!r}")
            step = int(step_text)
        else:
            step = 1

        if base == "*":
            start, end = low, high
        elif "-" in base:
            start_text, _, end_text = base.partition("-")
            if not start_text or not end_text or "-" in end_text:
                raise ValueError(f"invalid cron range: {item!r}")
            start = _field_value(start_text, low, high, names)
            end = _field_value(end_text, low, high, names)
            if start > end:
                raise ValueError(f"invalid cron range: {item!r}")
        else:
            start = _field_value(base, low, high, names)
            end = high if slash else start

        values.update(range(start, end + 1, step))

    return values


def _day_matches(
    moment: datetime,
    days_of_month: set[int],
    days_of_week: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    dom_matches = moment.day in days_of_month
    # Python's Monday is 0; cron's Sunday is 0.
    dow_matches = (moment.weekday() + 1) % 7 in days_of_week

    if dom_restricted and dow_restricted:
        return dom_matches or dow_matches
    return dom_matches and dow_matches


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields
    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    days_of_month = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12, _MONTH_NAMES)
    days_of_week = {
        value % 7 for value in _parse_field(dow_field, 0, 7, _DOW_NAMES)
    }

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=365 * 5)
    ordered_minutes = sorted(minutes)

    while current <= limit:
        if current.month not in months:
            if current.month == 12:
                current = current.replace(
                    year=current.year + 1,
                    month=1,
                    day=1,
                    hour=0,
                    minute=0,
                )
            else:
                current = current.replace(
                    month=current.month + 1,
                    day=1,
                    hour=0,
                    minute=0,
                )
            continue

        if not _day_matches(
            current,
            days_of_month,
            days_of_week,
            dom_restricted,
            dow_restricted,
        ):
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue

