from __future__ import annotations

_ALIGNMENTS = {"left", "right", "center"}


def _cell_text(value: object) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        if len(align) != columns:
            raise ValueError("alignment list has the wrong length")
        for value in align:
            if value is not None and value not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {value!r}")
        alignments = list(align)

    header_cells = [_cell_text(value) for value in header]
    row_cells = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend("" for _ in range(columns - len(cells)))
        row_cells.append(cells)

    widths = [max(3, len(cell)) for cell in header_cells]
    for cells in row_cells:
        for index, cell in enumerate(cells):
            widths[index] = max(widths[index], len(cell))

    lines = ["| " + " | ".join(
        _pad(cell, widths[index], alignments[index])
        for index, cell in enumerate(header_cells)
    ) + " |"]
    lines.append("| " + " | ".join(
        _delimiter_cell(widths[index], alignments[index])
        for index in range(columns)
    ) + " |")

    for cells in row_cells:
        lines.append("| " + " | ".join(
            _pad(cell, widths[index], alignments[index])
            for index, cell in enumerate(cells)
